async function resolveWorktreeGitDir(
  worktreePath: string,
): Promise<string | null> {
  try {
    const gitPointer = (await readFile(join(worktreePath, '.git'), 'utf-8'))
      .trim()
    if (!gitPointer.startsWith('gitdir:')) {
      return null
    }
    return resolve(worktreePath, gitPointer.slice('gitdir:'.length).trim())
  } catch {
    return null
  }
}

async function writeWorktreeBaseline(
  worktreePath: string,
  baseSha: string,
): Promise<void> {
  const gitDir = await resolveWorktreeGitDir(worktreePath)
  if (!gitDir) {
    logForDebugging(
      `[worktree] cannot write baseline: gitdir unresolvable for ${worktreePath}`,
    )
    return
  }
  try {
    await writeFile(join(gitDir, WORKTREE_BASELINE_FILE), baseSha, 'utf-8')
  } catch (error) {
    logForDebugging(
      `[worktree] failed to write baseline to ${gitDir}: ${error}`,
    )
  }
}

async function readWorktreeBaseline(
  worktreePath: string,
): Promise<string | null> {
  const gitDir = await resolveWorktreeGitDir(worktreePath)
  if (!gitDir) {
    return null
  }
  try {
    const baseline = (
      await readFile(join(gitDir, WORKTREE_BASELINE_FILE), 'utf-8')
    ).trim()
    return isValidGitSha(baseline) ? baseline : null
  } catch {
    return null
  }
}

