type BridgeWorktree = {
  worktreePath: string
  worktreeBranch?: string
  headCommit?: string
  gitRoot?: string
  hookBased?: boolean
}

async function cleanupBridgeWorktree(
  worktree: BridgeWorktree,
  logger: BridgeLogger,
  options?: { force?: boolean },
): Promise<void> {
  const forceCleanup =
    options?.force || (worktree.hookBased && worktree.headCommit === undefined)
  const { dirty, commitsAhead, gitError } = forceCleanup
    ? { dirty: false, commitsAhead: 0, gitError: false }
    : await getAgentWorktreeChanges(
        worktree.worktreePath,
        worktree.headCommit,
      )

  if (dirty || commitsAhead > 0) {
    const commitSummary = `${commitsAhead} ${plural(commitsAhead, 'commit')}`
    const reason = gitError
      ? 'git error checking changes'
      : dirty && commitsAhead > 0
        ? `uncommitted changes · ${commitSummary}`
        : dirty
          ? 'uncommitted changes'
          : commitSummary
    logger.logStatus(`kept worktree ${worktree.worktreePath} · ${reason}`)
    logForDebugging(
      `[bridge:worktree] kept ${worktree.worktreePath} dirty=${dirty} commitsAhead=${commitsAhead} gitError=${!!gitError}`,
    )
    return
  }

  if (
    await removeAgentWorktree(
      worktree.worktreePath,
      worktree.worktreeBranch,
      worktree.gitRoot,
      worktree.hookBased,
      'bridge',
    )
  ) {
    logger.logStatus(`removed worktree ${worktree.worktreePath}`)
  } else {
    logger.logStatus(
      `worktree removal failed, kept: ${worktree.worktreePath}`,
    )
  }
}

