let persistenceGeneration = 0
const persistenceCallbacks = {
  onTransportPersistenceReady: (
    writer: Parameters<typeof setInternalEventWriter>[0],
    readers: Parameters<typeof syncPersistence>[1],
  ): void => {
    const generation = ++persistenceGeneration
    void (async () => {
      try {
        const subagentIds =
          await listAllSubagentTranscriptIdsFromDisk()
        await syncPersistence(writer, readers, subagentIds)
      } catch (error) {
        logForDebugging(
          `[bridge:repl] Persistence sync failed: ${errorMessage(error)}`,
          { level: 'error' },
        )
      }
      if (generation !== persistenceGeneration) {
        logForDebugging(
          '[bridge:repl] Transport torn down during sync — skipping writer install',
        )
        return
      }
      setInternalEventWriter(writer)
      setInternalEventReader(readers.readMain, readers.readSubagents)
      logForDebugging(
        '[bridge:repl] Session persistence enabled — transcript writer + hydrate readers registered',
      )
    })()
  },
  onTransportPersistenceTeardown: (): void => {
    persistenceGeneration++
    clearInternalEventWriter()
  },
}

/** Stop forwarding new transcript entries to a transport that was torn down. */
export function clearInternalEventWriter(): void {
  getProject().clearInternalEventWriter()
}

