import pickBy from 'lodash-es/pickBy.js'
import uniqBy from 'lodash-es/uniqBy.js'
import type { Command } from '../../commands.js'
import type { AppState } from '../../state/AppStateStore.js'
import type { Tool } from '../../Tool.js'
import { getFeatureValue_CACHED_MAY_BE_STALE } from '../analytics/growthbook.js'
import { logForDebugging } from '../../utils/debug.js'
import { isEnvTruthy } from '../../utils/envUtils.js'
import { sleep } from '../../utils/sleep.js'
import {
  clearServerCache,
  connectToServer,
  getMcpToolsCommandsAndResources,
  getServerCacheKey,
} from './client.js'
import {
  dedupClaudeAiMcpServers,
  getMcpServerSignature,
} from './config.js'
import type {
  MCPServerConnection,
  ScopedMcpServerConfig,
  ServerResource,
} from './types.js'
import {
  excludeCommandsByServer,
  excludeResourcesByServer,
} from './utils.js'

type McpState = AppState['mcp']

export type HeadlessMcpStateAdapter = {
  getClients: () => McpState['clients']
  applyMcpUpdate: (update: (state: McpState) => McpState) => void
}

type CreateHeadlessMcpConnectionManagerOptions = {
  regularMcpConfigs: Record<string, ScopedMcpServerConfig>
  claudeaiConfigPromise: Promise<Record<string, ScopedMcpServerConfig>>
  state: HeadlessMcpStateAdapter
}

const MCP_SERVER_READINESS_TIMEOUT_MS = 5_000
const MCP_REMOTE_RETRY_DELAYS_MS = [500, 1_500, 4_000]
const RETRYABLE_REMOTE_MCP_TYPES = new Set([
  'http',
  'sse',
  'claudeai-proxy',
])

export function createHeadlessMcpConnectionManager({
  regularMcpConfigs,
  claudeaiConfigPromise,
  state,
}: CreateHeadlessMcpConnectionManagerOptions): { connect: () => Promise<void> } {
  const nonblocking = isEnvTruthy(process.env.MCP_CONNECTION_NONBLOCKING)

  async function connect(): Promise<void> {
    await connectWithMcpDeadline(
      nonblocking,
      connectMcpBatch(regularMcpConfigs, 'regular', state),
      '--mcp-config servers',
    )
    const claudeAi = claudeaiConfigPromise.then(claudeaiConfigs =>
      connectClaudeAiMcp({ claudeaiConfigs, regularMcpConfigs, state }),
    )
    await connectWithMcpDeadline(
      nonblocking,
      claudeAi,
      'claude.ai connectors',
    )
  }

  return { connect }
}

function connectMcpBatch(
  configs: Record<string, ScopedMcpServerConfig>,
  label: string,
  state: HeadlessMcpStateAdapter,
): Promise<void>[] {
  const names = Object.keys(configs)
  if (names.length === 0) return []

  state.applyMcpUpdate(previous => ({
    ...previous,
    clients: [
      ...previous.clients,
      ...Object.entries(configs).map(([name, config]) => ({
        name,
        type: 'pending' as const,
        config,
      })),
    ],
  }))

  const readinessResolvers = new Map<string, () => void>()
  const readiness = names.map(
    name =>
      new Promise<void>(resolve => readinessResolvers.set(name, resolve)),
  )

  void getMcpToolsCommandsAndResources(connection => {
    updateMcpConnection(state, connection)
    readinessResolvers.get(connection.client.name)?.()
  }, configs)
    .catch(error => {
      logForDebugging(`[MCP] ${label} connect error: ${error}`)
    })
    .finally(() => {
      for (const resolve of readinessResolvers.values()) resolve()
      if (
        getFeatureValue_CACHED_MAY_BE_STALE(
          'tengu_mcp_retry_failed_remote',
          true,
        )
      ) {
        void retryFailedRemoteMcpServers(configs, state).catch(error => {
          logForDebugging(`[MCP] ${label} retry error: ${error}`)
        })
      }
    })

  return readiness
}

function updateMcpConnection(
  state: HeadlessMcpStateAdapter,
  {
    client,
    tools,
    commands,
  }: {
    client: MCPServerConnection
    tools: Tool[]
    commands: Command[]
  },
): void {
  state.applyMcpUpdate(previous => {
    if (!previous.clients.some(existing => existing.name === client.name)) {
      if (client.type === 'connected') {
        void clearServerCache(client.name, client.config).catch(() => {})
      }
      return previous
    }
    return {
      ...previous,
      clients: previous.clients.map(existing =>
        existing.name === client.name ? client : existing,
      ),
      tools: uniqBy([...previous.tools, ...tools], 'name'),
      commands: uniqBy([...previous.commands, ...commands], 'name'),
    }
  })
}

async function retryFailedRemoteMcpServers(
  configs: Record<string, ScopedMcpServerConfig>,
  state: HeadlessMcpStateAdapter,
): Promise<void> {
  const retryable = Object.entries(configs).filter(([, config]) =>
    RETRYABLE_REMOTE_MCP_TYPES.has(config.type ?? ''),
  )
  if (retryable.length === 0) return

  for (const delayMs of MCP_REMOTE_RETRY_DELAYS_MS) {
    await sleep(delayMs)
    const failed = retryable.filter(([name]) =>
      state
        .getClients()
        .some(client => client.name === name && client.type === 'failed'),
    )
    if (failed.length === 0) {
      logForDebugging('[MCP] Retry: all remote servers connected, stopping')
      return
    }
    logForDebugging(
      `[MCP] Retry: ${failed.length} failed remote server(s) after ${delayMs}ms backoff`,
    )
    for (const [name, config] of failed) {
      connectToServer.cache.delete(getServerCacheKey(name, config))
    }
    await getMcpToolsCommandsAndResources(
      connection => updateMcpConnection(state, connection),
      Object.fromEntries(failed),
    )
  }

  const stillFailed = retryable.filter(([name]) =>
    state
      .getClients()
      .some(client => client.name === name && client.type === 'failed'),
  )
  if (stillFailed.length > 0) {
    logForDebugging(
      `[MCP] Retry: ${stillFailed.length} remote server(s) still failed after all retries: ${stillFailed.map(([name]) => name).join(', ')}`,
    )
  }
}

async function connectWithMcpDeadline(
  nonblocking: boolean,
  connection: Promise<void>[] | Promise<Promise<void>[]>,
  label: string,
): Promise<void> {
  if (nonblocking) {
    void Promise.resolve(connection).catch(() => {})
    logForDebugging(
      `[MCP] ${label} running fully async (MCP_CONNECTION_NONBLOCKING)`,
    )
    return
  }

  const startedAt = Date.now()
  let readiness: Promise<void>[]
  if (Array.isArray(connection)) {
    readiness = connection
  } else {
    let timer: ReturnType<typeof setTimeout> | undefined
    const result = await Promise.race([
      connection,
      new Promise<'deadline'>(resolve => {
        timer = setTimeout(
          value => value('deadline'),
          MCP_SERVER_READINESS_TIMEOUT_MS,
          resolve,
        )
      }),
    ])
    if (timer) clearTimeout(timer)
    if (result === 'deadline') {
      void connection.catch(() => {})
      logForDebugging(
        `[MCP] ${label} not ready after ${MCP_SERVER_READINESS_TIMEOUT_MS}ms — proceeding; background connection continues`,
      )
      return
    }
    readiness = result
  }

  const remainingMs = Math.max(
    0,
    MCP_SERVER_READINESS_TIMEOUT_MS - (Date.now() - startedAt),
  )
  const notReady = await waitForMcpReadiness(readiness, remainingMs)
  if (notReady > 0) {
    logForDebugging(
      `[MCP] ${label}: ${notReady}/${readiness.length} not ready after ${MCP_SERVER_READINESS_TIMEOUT_MS}ms — proceeding; background connection continues`,
    )
  }
}

async function connectClaudeAiMcp({
  claudeaiConfigs,
  regularMcpConfigs,
  state,
}: {
  claudeaiConfigs: Record<string, ScopedMcpServerConfig>
  regularMcpConfigs: Record<string, ScopedMcpServerConfig>
  state: HeadlessMcpStateAdapter
}): Promise<void>[] {
  if (Object.keys(claudeaiConfigs).length > 0) {
    const claudeAiSignatures = new Set<string>()
    for (const config of Object.values(claudeaiConfigs)) {
      const signature = getMcpServerSignature(config)
      if (signature) claudeAiSignatures.add(signature)
    }
    const suppressed = new Set<string>()
    for (const [name, config] of Object.entries(regularMcpConfigs)) {
      if (!name.startsWith('plugin:')) continue
      const signature = getMcpServerSignature(config)
      if (signature && claudeAiSignatures.has(signature)) suppressed.add(name)
    }
    if (suppressed.size > 0) {
      logForDebugging(
        `[MCP] Lazy dedup: suppressing ${suppressed.size} plugin server(s) that duplicate claude.ai connectors: ${[...suppressed].join(', ')}`,
      )
      for (const client of state.getClients()) {
        if (!suppressed.has(client.name) || client.type !== 'connected') continue
        client.client.onclose = undefined
        void clearServerCache(client.name, client.config).catch(() => {})
      }
      state.applyMcpUpdate(previous => {
        const clients = previous.clients.filter(
          client => !suppressed.has(client.name),
        )
        const tools = previous.tools.filter(
          tool => !tool.mcpInfo || !suppressed.has(tool.mcpInfo.serverName),
        )
        let commands = [...previous.commands]
        let resources = previous.resources as Record<string, ServerResource[]>
        for (const name of suppressed) {
          commands = excludeCommandsByServer(commands, name)
          resources = excludeResourcesByServer(resources, name)
        }
        return { ...previous, clients, tools, commands, resources }
      })
    }
  }

  const nonPluginConfigs = pickBy(
    regularMcpConfigs,
    (_config, name) => !name.startsWith('plugin:'),
  )
  const { servers } = dedupClaudeAiMcpServers(
    claudeaiConfigs,
    nonPluginConfigs,
  )
  return connectMcpBatch(servers, 'claudeai', state)
}

async function waitForMcpReadiness(
  readiness: Promise<void>[],
  timeoutMs: number,
): Promise<number> {
  if (readiness.length === 0) return 0
  let timer: ReturnType<typeof setTimeout> | undefined
  const deadline = new Promise<'deadline'>(resolve => {
    timer = setTimeout(value => value('deadline'), timeoutMs, resolve)
  })
  try {
    const results = await Promise.all(
      readiness.map(connection =>
        Promise.race([
          connection.then(
            () => 'settled' as const,
            () => 'settled' as const,
          ),
          deadline,
        ]),
      ),
    )
    return results.filter(result => result === 'deadline').length
  } finally {
    if (timer) clearTimeout(timer)
  }
}

